<script setup>
import {ref, computed} from 'vue'
import grammar from '../data/visuals.json'
import example from '../data/branch-example.json'
const props=defineProps({level:{default:1},interactive:Boolean,recorded:Boolean})
const selected=ref('');const selectedId=ref(props.recorded?'a':'')
const selectedRecord=computed(()=>props.recorded?example[selectedId.value]:null)
const changeLines=computed(()=>selectedRecord.value?.diff?.split('\n').filter(line=>/^[+-](?![+-])/.test(line)).join('\n')||'')
const nodes=[{id:'parent',x:70,y:175,label:'Parent code',detail:'Ask for two changes to the same starting code. Both candidates use the same experiment settings.'},{id:'a',x:270,y:80,label:'Candidate A',detail:'Read Candidate A’s proposed edit to the model, loss, or training code. Its explanation tells you what the agent expects the change to do.'},{id:'b',x:270,y:275,label:'Candidate B',detail:'Read Candidate B’s alternative change to that same starting code. Test it separately so you can compare the outcomes.'},{id:'pa',x:465,y:80,label:'Train + validate A',detail:'Train Candidate A on the training dates, then measure its validation error. Open the saved prediction to see what it missed.'},{id:'pb',x:465,y:275,label:'Train + validate B',detail:'Train Candidate B with the same data and settings. If training fails, inspect its error before deciding what to try next.'},{id:'compose',x:665,y:175,label:'Choose changes',detail:'Give the agent both test results. Ask it to choose a candidate, combine changes, or retain the starting version.'},{id:'test',x:865,y:175,label:'Test composition',detail:'Train and score the chosen code. Adopt it only if its fixed validation error is strictly lower; equal, failed or worse results retain the parent.'},{id:'next',x:1050,y:175,label:'Save selection',detail:'Save the tested selected code and lesson, then start round two from that version. Selection is a decision, not another training execution.'}]
const visible=n=>n.id==='parent'||(props.level>=1&&['a','b'].includes(n.id))||(props.level>=2&&['pa','pb'].includes(n.id))||(props.level>=3&&n.id==='compose')||(props.level>=4&&n.id==='test')||(props.level>=5&&n.id==='next')
const choose=n=>{if(props.interactive){selected.value=n.detail;selectedId.value=n.id}}
</script>
<template><div class="research-branches" :class="{recorded}"><svg viewBox="0 0 1140 375" :role="interactive?'group':'img'" aria-label="Two proposed code changes train independently, composition reviews their evidence, the composition runs, and a retained version begins round two">
<g fill="none" stroke-width="3"><path v-if="level>=1" d="M70 175C150 175 150 80 270 80" :stroke="grammar.colors.candidate_a"/><path v-if="level>=1" d="M70 175C150 175 150 275 270 275" :stroke="grammar.colors.candidate_b"/><path v-if="level>=2" d="M270 80H465" :stroke="grammar.colors.candidate_a"/><path v-if="level>=2" d="M270 275H465" :stroke="grammar.colors.candidate_b"/><path v-if="level>=3" d="M465 80C570 80 565 175 665 175M465 275C570 275 565 175 665 175" stroke="#638382" :stroke-dasharray="grammar.edges.evidence.dash"/><path v-if="level>=4" d="M665 175H865" stroke="#163c43"/><path v-if="level>=5" d="M865 175H1050" :stroke="grammar.colors.selection" stroke-width="5"/></g>
<g v-if="level>=2"><text x="367" y="57" text-anchor="middle" class="small">Review diff</text><text x="367" y="252" text-anchor="middle" class="small">Review diff</text><line x1="365" y1="69" x2="365" y2="91" stroke="#163c43" stroke-width="3"/><line x1="365" y1="264" x2="365" y2="286" stroke="#163c43" stroke-width="3"/></g>
<g v-for="n in nodes.filter(visible)" :key="n.id" class="node" :tabindex="interactive?0:-1" :role="interactive?'button':undefined" :aria-label="n.label" :aria-pressed="interactive?selectedId===n.id:undefined" @click="choose(n)" @keydown.enter="choose(n)" @keydown.space.prevent="choose(n)"><rect :x="n.x-90" :y="n.y-20" width="180" height="90" fill="transparent" pointer-events="all"/><circle :cx="n.x" :cy="n.y" r="15" :stroke="selectedId===n.id?'#f1ca70':'none'" stroke-width="5" :fill="['a','pa'].includes(n.id)?grammar.colors.candidate_a:['b','pb'].includes(n.id)?grammar.colors.candidate_b:n.id==='compose'?grammar.colors.composition:n.id==='next'?grammar.colors.selection:n.id==='parent'?grammar.colors.parent:grammar.colors.execution"/><text :x="n.x" :y="n.y+48" text-anchor="middle">{{n.label}}</text><text v-if="n.id==='compose'" :x="n.x" :y="n.y+72" text-anchor="middle" class="small">keep, combine, or retain</text></g>
</svg><div v-if="interactive && recorded" class="recorded-detail" aria-live="polite"><div><strong>{{selectedRecord.title}}</strong><p>{{selectedRecord.explanation}}</p><p v-if="selectedRecord.error!=null">Validation MAE: <strong>{{selectedRecord.error.toFixed(6)}}</strong></p></div><div><pre v-if="changeLines">{{changeLines}}</pre><p><a :href="selectedRecord.url" target="_blank" rel="noopener">Open this recorded event ↗</a> · <a :href="selectedRecord.artifact" target="_blank" rel="noopener">Saved files ↗</a></p></div></div><div v-else-if="interactive" class="branch-detail" aria-live="polite">{{selected||'Select a step to see what code or result passes to the next one.'}}</div><div class="legend"><span>Solid line: code moves to the next step</span><span>Dashed line: test results are reviewed</span><span>{{grammar.labels.color}}</span></div></div></template>
<style scoped>svg{width:100%;height:335px}text{font:20px 'IBM Plex Sans';fill:#163c43}.small{font-size:15px}.node[role=button]{cursor:pointer}.node:focus{outline:3px solid #f1ca70}.recorded svg{height:285px}.recorded-detail{display:grid;grid-template-columns:1fr 1fr;gap:22px;font-size:20px;line-height:1.35;min-height:150px;border-left:4px solid #237a6c;padding:12px 18px;background:#e8ebdf}.recorded-detail p{margin:6px 0}.recorded-detail pre{font-size:14px!important;line-height:1.5!important;white-space:pre-wrap;overflow-wrap:anywhere;padding:8px!important}.recorded .legend{font-size:17px;margin-top:9px}</style>
